-- =========================================================
-- Medical Catalog Service (PostgreSQL) – DB + Tables + Seed
-- IDs = INT GENERATED BY DEFAULT AS IDENTITY (NO explicit ID inserts)
-- =========================================================
DROP DATABASE IF EXISTS medical_catalog_db;
CREATE DATABASE medical_catalog_db
  TEMPLATE template0
  ENCODING 'UTF8'
  LC_COLLATE 'en_US.UTF-8'
  LC_CTYPE   'en_US.UTF-8';
ALTER DATABASE medical_catalog_db SET TIMEZONE TO 'Asia/Ho_Chi_Minh';
\c medical_catalog_db

-- ======================
-- 1) DDL – CREATE TABLES
-- ======================

-- Form (dosage form)
CREATE TABLE IF NOT EXISTS "Form" (
  "FormID"      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  -- 1..N
  "FormName"    VARCHAR(100) NOT NULL UNIQUE,
  "Description" TEXT,
  "CreatedAt"   TIMESTAMPTZ DEFAULT NOW(),
  "UpdatedAt"   TIMESTAMPTZ DEFAULT NOW()
);

-- Unit (measurement unit)
CREATE TABLE IF NOT EXISTS "Unit" (
  "UnitID"      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  -- 1..N
  "UnitName"    VARCHAR(50) NOT NULL UNIQUE,
  "Description" TEXT,
  "CreatedAt"   TIMESTAMPTZ DEFAULT NOW(),
  "UpdatedAt"   TIMESTAMPTZ DEFAULT NOW()
);

-- Manufacturer
CREATE TABLE IF NOT EXISTS "Manufacturer" (
  "ManufacturerID"   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 1..N
  "ManufacturerName" VARCHAR(150) NOT NULL UNIQUE,
  "Address"          VARCHAR(255),
  "Country"          VARCHAR(100),
  "Email"            VARCHAR(150),
  "PhoneNumber"      VARCHAR(30),
  "CreatedAt"        TIMESTAMPTZ DEFAULT NOW(),
  "UpdatedAt"        TIMESTAMPTZ DEFAULT NOW()
);

-- Medicine
CREATE TABLE IF NOT EXISTS "Medicine" (
  "MedicineID"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 1..N
  "MedicineName"      VARCHAR(150) NOT NULL,
  "Ingredient"        TEXT,
  "FormID"            INT NOT NULL REFERENCES "Form"("FormID") ON DELETE RESTRICT,
  "UnitID"            INT NOT NULL REFERENCES "Unit"("UnitID") ON DELETE RESTRICT,
  "Packaging"         VARCHAR(200),
  "DosageInstruction" TEXT,
  "Indication"        TEXT,
  "Contraindication"  TEXT,
  "SideEffect"        TEXT,
  "Storage"           TEXT,
  "ManufacturerID"    INT REFERENCES "Manufacturer"("ManufacturerID") ON DELETE SET NULL,
  "Price"             NUMERIC(12,2),
  "InStock"           BOOLEAN NOT NULL DEFAULT TRUE,
  "Status"            VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK ("Status" IN ('ACTIVE','INACTIVE')),
  "CreatedAt"         TIMESTAMPTZ DEFAULT NOW(),
  "UpdatedAt"         TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_medicine_form ON "Medicine"("FormID");
CREATE INDEX IF NOT EXISTS idx_medicine_unit ON "Medicine"("UnitID");
CREATE INDEX IF NOT EXISTS idx_medicine_manu ON "Medicine"("ManufacturerID");

-- Test (diagnostics) – DepartmentID is INT to match EmployeeService
CREATE TABLE IF NOT EXISTS "Test" (
  "TestID"       INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 1..N
  "TestName"     VARCHAR(150) NOT NULL,
  "Description"  TEXT,
  "Price"        NUMERIC(12,2),
  "DepartmentID" INT NOT NULL,  -- cross-service; INT in EmployeeService
  "CreatedAt"    TIMESTAMPTZ DEFAULT NOW(),
  "UpdatedAt"    TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_test_department ON "Test"("DepartmentID");

